for(const p of profiles){
  const r=p.profile||{};
  const tx=Array.isArray(r.recent_transactions)?r.recent_transactions.slice(0,5):[];
  secondHopTx+=tx.length;
  const seed=String(p.seed||'').toLowerCase();
  const local=new Set();
  for(const x of tx){
    const f=String(x.from||'').toLowerCase(),t=String(x.to||'').toLowerCase();
    if(f&&t){
      secondHopEdges++;
      const other=f===seed?t:f;
      if(other&&other!==seed){local.add(other);secondHopCounterparties.add(other)}
    }
  }
  secondHopNodes+=local.size+(tx.length?1:0);
  if(local.size>=4)secondHopFlags.push('seed_has_broad_counterparty_activity');
  if(tx.length>=5){
    const counts=new Map();
    for(const x of tx){
      const f=String(x.from||'').toLowerCase(),t=String(x.to||'').toLowerCase();
      const other=f===seed?t:f;
      if(other)counts.set(other,(counts.get(other)||0)+1);
    }
    const top=Math.max(0,...counts.values());
    if(top>=3)secondHopFlags.push('seed_has_repeated_counterparty_edge');
  }
}
