  expansionCoverage*25+
  Math.min(secondHopCounterparties.size/8,1)*25+
  Math.min(secondHopEdges/10,1)*20+
  Math.min(secondHopTx/10,1)*15+
  Math.min(secondHopFlags.length/2,1)*15
