  contractRatio:Number(li.contract_interaction_ratio??0),
  tokenDiversity:Number(li.token_diversity??0)
};
const baseScore=Math.round(Math.min(100,
  20*Math.min(baseSignals.counterparties/5,1)+
  20*Math.max(0,Math.min(baseSignals.edgeShare,1))+
  20*Math.max(0,Math.min(baseSignals.flowImbalance,1))+
  15*Math.max(0,Math.min(baseSignals.contractRatio,1))+
  15*Math.min(baseSignals.tokenDiversity/5,1)
));
const finalGraphScore=Math.round(baseScore*0.65+multiScore*0.35);
